import { sql } from "drizzle-orm";
import { char, customType, timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: a UUID generated by Postgres. Better Auth is told to use database UUIDs too. */
export const pk = () => uuid("id").primaryKey().defaultRandom();

export const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const ts = (name: string) => timestamp(name, { withTimezone: true });

/** ISO 4217 currency code. Money is always an integer in minor units next to one of these. */
export const currencyCol = (name = "currency") => char(name, { length: 3 }).notNull().default("ILS");

/** Postgres full-text search vector. Read only, always generated from other columns. */
export const tsvector = customType<{ data: string }>({
  dataType() {
    return "tsvector";
  },
});

export const nonNegative = (column: string) => sql.raw(`"${column}" >= 0`);
